/**
 * Unpadded base64url ("base64 with URL and filename safe alphabet", RFC 4648
 * §5) exactly as python-jose's `base64url_encode` / `base64url_decode` behave:
 * the trailing `=` padding is stripped on encode and re-added on decode.
 */

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const REVERSE = (() => {
  const table = new Int16Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i += 1) {
    table[ALPHABET.charCodeAt(i)] = i;
  }
  // Accept the standard alphabet too, like base64.urlsafe_b64decode's inverse.
  table['+'.charCodeAt(0)] = 62;
  table['/'.charCodeAt(0)] = 63;
  return table;
})();

/**
 * @param {Uint8Array} bytes
 * @returns {string} unpadded base64url text
 */
export function base64urlEncode(bytes) {
  let out = '';
  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63] + ALPHABET[n & 63];
  }
  const rest = bytes.length - i;
  if (rest === 1) {
    const n = bytes[i] << 16;
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
  } else if (rest === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63];
  }
  return out;
}

/**
 * @param {string} text unpadded or padded base64url text
 * @returns {Uint8Array}
 */
export function base64urlDecode(text) {
  const clean = String(text).replace(/=+$/, '');
  const groups = [];
  for (let i = 0; i < clean.length; i += 1) {
    const code = clean.charCodeAt(i);
    const value = code < 128 ? REVERSE[code] : -1;
    if (value < 0) {
      throw new Error('Invalid base64url character');
    }
    groups.push(value);
  }
  if (groups.length % 4 === 1) {
    throw new Error('Invalid base64url length');
  }

  const out = [];
  for (let i = 0; i < groups.length; i += 4) {
    const chunk = groups.length - i;
    const b0 = groups[i];
    const b1 = groups[i + 1] || 0;
    const b2 = chunk > 2 ? groups[i + 2] : 0;
    const b3 = chunk > 3 ? groups[i + 3] : 0;
    const n = (b0 << 18) | (b1 << 12) | (b2 << 6) | b3;
    out.push((n >> 16) & 0xff);
    if (chunk > 2) out.push((n >> 8) & 0xff);
    if (chunk > 3) out.push(n & 0xff);
  }
  return new Uint8Array(out);
}

