/**
 * @param {Uint8Array} message
 * @returns {Uint8Array} the 32-byte digest
 */
export function sha256(message) {
  const bitLength = message.length * 8;
  const padded = new Uint8Array(((message.length + 9 + 63) & ~63) >>> 0);
  padded.set(message);
  padded[message.length] = 0x80;

  // 64-bit big-endian bit count in the final 8 bytes.
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  const tail = padded.length - 8;
  padded[tail] = (high >>> 24) & 0xff;
  padded[tail + 1] = (high >>> 16) & 0xff;
  padded[tail + 2] = (high >>> 8) & 0xff;
  padded[tail + 3] = high & 0xff;
  padded[tail + 4] = (low >>> 24) & 0xff;
  padded[tail + 5] = (low >>> 16) & 0xff;
  padded[tail + 6] = (low >>> 8) & 0xff;
  padded[tail + 7] = low & 0xff;

  const state = INITIAL_STATE.slice();
  const w = new Uint32Array(64);
  for (let offset = 0; offset < padded.length; offset += BLOCK_SIZE) {
    compress(state, w, padded, offset);
  }

  const digest = new Uint8Array(DIGEST_SIZE);
  for (let i = 0; i < 8; i += 1) {
    digest[i * 4] = (state[i] >>> 24) & 0xff;
    digest[i * 4 + 1] = (state[i] >>> 16) & 0xff;
    digest[i * 4 + 2] = (state[i] >>> 8) & 0xff;
    digest[i * 4 + 3] = state[i] & 0xff;
  }
  return digest;
}

