/**
 * HMAC (RFC 2104) on top of the local SHA-256 implementation, plus the
 * constant-time comparison python-jose uses when verifying a signature.
 */

import { BLOCK_SIZE, DIGEST_SIZE, sha256 } from './sha256.mjs';

/**
 * @param {Uint8Array} key
 * @param {Uint8Array} message
 * @returns {Uint8Array} 32-byte MAC
 */
export function hmacSha256(key, message) {
  let normalizedKey = key;
  if (normalizedKey.length > BLOCK_SIZE) {
    normalizedKey = sha256(normalizedKey);
  }

  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  const outer = new Uint8Array(BLOCK_SIZE + DIGEST_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i += 1) {
    const byte = i < normalizedKey.length ? normalizedKey[i] : 0;
    inner[i] = byte ^ 0x36;
    outer[i] = byte ^ 0x5c;
  }
  inner.set(message, BLOCK_SIZE);
  outer.set(sha256(inner), BLOCK_SIZE);

  return sha256(outer);
}

/**
 * `hmac.compare_digest` equivalent: length-independent early exit, but no
 * short-circuit on the first differing byte.
 *
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 */
export function constantTimeEqual(a, b) {
  if (a.length !== b.length) {
    return false;
  }
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

