/**
 * A minimal, faithful port of CPython's `json` encoder/decoder surface that
 * python-jose relies on: `json.dumps(obj)` with the library's exact defaults
 * (`ensure_ascii=True`, `separators=(', ', ': ')` collapsed to the compact
 * form used for JWT segments) and `json.loads`.
 */

const SHORT_ESCAPES = {
  0x08: '\\b',
  0x09: '\\t',
  0x0a: '\\n',
  0x0c: '\\f',
  0x0d: '\\r',
  0x22: '\\"',
  0x5c: '\\\\',
};

function hex4(code) {
  return code.toString(16).padStart(4, '0');
}

/** `json.encoder.py_encode_basestring_ascii` */
export function encodeStringAscii(value) {
  let out = '"';
  for (let i = 0; i < value.length; i += 1) {
    // Iterating UTF-16 units reproduces CPython's surrogate-pair output for
    // astral characters (e.g. U+1F600 -> "😀").
    const code = value.charCodeAt(i);
    const short = SHORT_ESCAPES[code];
    if (short !== undefined) {
      out += short;
    } else if (code < 0x20 || code >= 0x7f) {
      out += `\\u${hex4(code)}`;
    } else {
      out += value[i];
    }
  }
  return `${out}"`;
}

function dumpNumber(value) {
  if (!Number.isFinite(value)) {
    return value > 0 ? 'Infinity' : Number.isNaN(value) ? 'NaN' : '-Infinity';
  }
  if (Number.isInteger(value) && Object.is(value, Math.trunc(value))) {
    return String(value);
  }
  // CPython uses repr(float) which matches JS shortest round-trip formatting
  // apart from exponent spelling, normalised here.
  return String(value).replace(/e([+-])(\d)$/, 'e$10$2');
}

/**
 * @param {unknown} value
 * @param {{itemSeparator?: string, keySeparator?: string}} [options]
 * @returns {string}
 */
export function dumps(value, options = {}) {
  const itemSeparator = options.itemSeparator ?? ',';
  const keySeparator = options.keySeparator ?? ':';

  const encode = (node) => {
    if (node === null || node === undefined) {
      return 'null';
    }
    if (typeof node === 'boolean') {
      return node ? 'true' : 'false';
    }
    if (typeof node === 'number') {
      return dumpNumber(node);
    }
    if (typeof node === 'string') {
      return encodeStringAscii(node);
    }
    if (Array.isArray(node)) {
      return `[${node.map(encode).join(itemSeparator)}]`;
    }
    if (node instanceof Map) {
      const parts = [];
      for (const [key, item] of node) {
        parts.push(`${encodeStringAscii(String(key))}${keySeparator}${encode(item)}`);
      }
      return `{${parts.join(itemSeparator)}}`;
    }
    if (typeof node === 'object') {
      const parts = [];
      for (const key of Object.keys(node)) {
        parts.push(`${encodeStringAscii(key)}${keySeparator}${encode(node[key])}`);
      }
      return `{${parts.join(itemSeparator)}}`;
    }
    throw new TypeError(`Object of type ${typeof node} is not JSON serializable`);
  };

  return encode(value);
}

/**
 * `json.loads`; throws on malformed input just like `ValueError` would.
 * @param {string} text
 */
export function loads(text) {
  return JSON.parse(text);
}

