/**
 * A focused port of CPython's `argparse.ArgumentParser` covering the feature
 * set this program uses: long options with `--opt value` / `--opt=value`,
 * unique-prefix abbreviation, the automatic `-h/--help` action, `required=True`
 * enforcement, and argparse's exact usage/error/help text and exit codes.
 */

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(argumentName ? `argument ${argumentName}: ${message}` : message);
    this.name = 'ArgumentError';
  }
}

function baseName(pathLike) {
  const normalized = String(pathLike).replace(/[/\\]+$/, '');
  const index = Math.max(normalized.lastIndexOf('/'), normalized.lastIndexOf('\\'));
  return index === -1 ? normalized : normalized.slice(index + 1);
}

/** `argparse` derives `prog` from `os.path.basename(sys.argv[0])`. */
export function defaultProg(argv = process.argv) {
  return baseName(argv[1] ?? 'program');
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, exitOnError?: boolean}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? defaultProg();
    this.actions = [];
    this.optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * @param {string[]|string} flags
   * @param {{action?: string, required?: boolean, dest?: string, metavar?: string, help?: string, type?: Function, default?: unknown}} [spec]
   */
  addArgument(flags, spec = {}) {
    const optionStrings = Array.isArray(flags) ? flags.slice() : [flags];
    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = spec.dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');

    const action = {
      optionStrings,
      dest,
      action: spec.action ?? 'store',
      required: spec.required ?? false,
      metavar: spec.metavar ?? dest.toUpperCase(),
      help: spec.help ?? null,
      type: spec.type ?? String,
      default: spec.default ?? null,
    };

    this.actions.push(action);
    for (const flag of optionStrings) {
      this.optionStringActions.set(flag, action);
    }
    return action;
  }

  /** `_get_action_name`: option actions are named by their joined flags. */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  formatUsage() {
    const parts = [];
    for (const action of this.actions) {
      const flag = action.optionStrings[0];
      if (action.action === 'help') {
        parts.push(`[${flag}]`);
      } else if (action.required) {
        parts.push(`${flag} ${action.metavar}`);
      } else {
        parts.push(`[${flag} ${action.metavar}]`);
      }
    }
    return `usage: ${this.prog}${parts.length ? ` ${parts.join(' ')}` : ''}\n`;
  }

  formatHelp() {
    let out = this.formatUsage();
    out += '\noptions:\n';
    for (const action of this.actions) {
      let invocation;
      if (action.action === 'help') {
        invocation = action.optionStrings.join(', ');
      } else {
        invocation = action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
      }

      const indented = `  ${invocation}`;
      if (!action.help) {
        out += `${indented}\n`;
      } else if (indented.length <= 22) {
        // argparse pads the invocation out to its max_help_position (24).
        out += `${indented.padEnd(24)}${action.help}\n`;
      } else {
        out += `${indented}\n${' '.repeat(24)}${action.help}\n`;
      }
    }
    return out;
