/**
 * Supported algorithms and the HMAC key wrapper, matching python-jose's
 * `jose.jwk.HMACKey` construction rules and rejections.
 */

import { utf8Encode } from '../codec/utf8.mjs';
import { hmacSha256, constantTimeEqual } from '../hash/hmac.mjs';
import { JWKError } from './errors.mjs';

export const ALGORITHMS = {
  NONE: 'none',
  HS256: 'HS256',
  HS384: 'HS384',
  HS512: 'HS512',
};

export const HMAC_ALGORITHMS = new Set([ALGORITHMS.HS256, ALGORITHMS.HS384, ALGORITHMS.HS512]);

/** Keys that are clearly asymmetric material must not be used as HMAC secrets. */
const INVALID_KEY_MARKERS = [
  '-----BEGIN PUBLIC KEY-----',
  '-----BEGIN RSA PUBLIC KEY-----',
  '-----BEGIN CERTIFICATE-----',
  'ssh-rsa',
];

export class HMACKey {
  /**
   * @param {string|Uint8Array} key
   * @param {string} algorithm
   */
  constructor(key, algorithm) {
    if (!HMAC_ALGORITHMS.has(algorithm)) {
      throw new JWKError(`hash_alg: ${algorithm} is not a valid hash algorithm`);
    }
    if (algorithm !== ALGORITHMS.HS256) {
      // Only HS256 is implemented locally; the others would need SHA-384/512.
      throw new JWKError(`hash_alg: ${algorithm} is not supported`);
    }
    this.algorithm = algorithm;

    if (typeof key !== 'string' && !(key instanceof Uint8Array)) {
      throw new JWKError('Expecting a string- or bytes-formatted key.');
    }
    const asText = typeof key === 'string' ? key : null;
    if (asText !== null && INVALID_KEY_MARKERS.some((marker) => asText.includes(marker))) {
      throw new JWKError(
        'The specified key is an asymmetric key or x509 certificate and should not be used as an HMAC secret.',
      );
    }
    this.preparedKey = typeof key === 'string' ? utf8Encode(key) : key;
  }

  /**
   * @param {Uint8Array} message
   * @returns {Uint8Array}
   */
  sign(message) {
    return hmacSha256(this.preparedKey, message);
  }

  /**
   * @param {Uint8Array} message
   * @param {Uint8Array} signature
   */
  verify(message, signature) {
    return constantTimeEqual(this.sign(message), signature);
  }
}

/**
 * `jose.jwk.construct` for the algorithms handled here.
 * @param {string|Uint8Array|HMACKey} key
 * @param {string} algorithm
 */
export function constructKey(key, algorithm) {
  if (key instanceof HMACKey) {
    return key;
  }
  return new HMACKey(key, algorithm);
}

