/**
 * JWS compact serialization (`jose.jws`): sign, load and verify.
 */

import { base64urlEncode, base64urlDecode } from '../codec/base64url.mjs';
import { utf8Encode, utf8Decode } from '../codec/utf8.mjs';
import { dumps, loads } from '../json/py_json.mjs';
import { ALGORITHMS } from './keys.mjs';
import { constructKey } from './keys.mjs';
import { JWSError, JWSSignatureError, JWSAlgorithmError } from './errors.mjs';

/** `_encode_header`: `{"typ": "JWT", "alg": alg}` serialized with sorted keys. */
function encodeHeader(algorithm, additionalHeaders) {
  const header = { typ: 'JWT', alg: algorithm };
  if (additionalHeaders) {
    Object.assign(header, additionalHeaders);
  }
  const sorted = new Map(Object.keys(header).sort().map((key) => [key, header[key]]));
  return base64urlEncode(utf8Encode(dumps(sorted)));
}

/** `_encode_payload`: mappings become compact JSON, bytes pass through. */
function encodePayload(payload) {
  if (payload instanceof Uint8Array) {
    return base64urlEncode(payload);
  }
  if (typeof payload === 'string') {
    return base64urlEncode(utf8Encode(payload));
  }
  return base64urlEncode(utf8Encode(dumps(payload)));
}

/**
 * `jws.sign(payload, key, headers=None, algorithm='HS256')`
 * @returns {string} the compact JWS
 */
export function sign(payload, key, { headers = null, algorithm = ALGORITHMS.HS256 } = {}) {
  if (algorithm === ALGORITHMS.NONE) {
    throw new JWSAlgorithmError('Algorithm none is not supported.');
  }
  const encodedHeader = encodeHeader(algorithm, headers);
  const encodedPayload = encodePayload(payload);
  const signingInput = `${encodedHeader}.${encodedPayload}`;

  const preparedKey = constructKey(key, algorithm);
  const signature = preparedKey.sign(utf8Encode(signingInput));
  return `${signingInput}.${base64urlEncode(signature)}`;
}

/**
 * `jws._load`: splits and decodes the three segments.
 * @param {string} token
 */
export function load(token) {
  const text = token instanceof Uint8Array ? utf8Decode(token) : String(token);
  const lastDot = text.lastIndexOf('.');
  if (lastDot === -1) {
    throw new JWSError('Not enough segments');
  }
  const signingInput = text.slice(0, lastDot);
  const cryptoSegment = text.slice(lastDot + 1);
  const firstDot = signingInput.indexOf('.');
  if (firstDot === -1) {
    throw new JWSError('Not enough segments');
  }
  const headerSegment = signingInput.slice(0, firstDot);
  const claimsSegment = signingInput.slice(firstDot + 1);

  let header;
  try {
    header = loads(utf8Decode(base64urlDecode(headerSegment)));
  } catch (err) {
    throw new JWSError(`Invalid header string: ${err.message}`);
  }
  if (header === null || typeof header !== 'object' || Array.isArray(header)) {
    throw new JWSError('Invalid header string: must be a json object');
  }

  let payload;
  try {
    payload = base64urlDecode(claimsSegment);
  } catch (err) {
    throw new JWSError(`Invalid payload padding: ${err.message}`);
  }

  let signature;
  try {
    signature = base64urlDecode(cryptoSegment);
  } catch (err) {
    throw new JWSError(`Invalid crypto padding: ${err.message}`);
  }

  return { header, payload, signature, signingInput: utf8Encode(signingInput) };
}

function verifySignature(signingInput, header, signature, key, algorithms) {
  const alg = header.alg;
  if (!alg) {
    throw new JWSError('No algorithm was specified in the JWS header.');
  }
  if (algorithms !== null && algorithms !== undefined && !algorithms.includes(alg)) {
    throw new JWSError('The specified alg value is not allowed');
  }

  let preparedKey;
  try {
    preparedKey = constructKey(key, alg);
  } catch (err) {
    throw new JWSError(err.message);
  }
  if (!preparedKey.verify(signingInput, signature)) {
    throw new JWSSignatureError('Signature verification failed.');
  }
}

/**
 * `jws.verify(token, key, algorithms, verify=True)`
 * @returns {Uint8Array} the raw payload bytes
 */
export function verify(token, key, algorithms, doVerify = true) {
  const { header, payload, signature, signingInput } = load(token);
  if (doVerify) {
    verifySignature(signingInput, header, signature, key, algorithms);
  }
  return payload;
}

