/**
 * Registered-claim validation, mirroring `jose.jwt`'s `_validate_claims` and
 * the `options` flags that switch each check on or off.
 */

import { JWTError, JWTClaimsError, ExpiredSignatureError } from './errors.mjs';

export const DEFAULT_OPTIONS = {
  verify_signature: true,
  verify_aud: true,
  verify_iat: true,
  verify_exp: true,
  verify_nbf: true,
  verify_iss: true,
  verify_sub: true,
  verify_jti: true,
  verify_at_hash: true,
  require_aud: false,
  require_iat: false,
  require_exp: false,
  require_nbf: false,
  require_iss: false,
  require_sub: false,
  require_jti: false,
  require_at_hash: false,
  leeway: 0,
};

function has(claims, name) {
  return Object.prototype.hasOwnProperty.call(claims, name);
}

function now() {
  return Math.floor(Date.now() / 1000);
}

function asTimestamp(value, claimName) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new JWTClaimsError(`${claimName} claim must be a number.`);
  }
  return value;
}

function validateIat(claims) {
  if (!has(claims, 'iat')) {
    return;
  }
  asTimestamp(claims.iat, 'Issued At');
}

function validateNbf(claims, leeway) {
  if (!has(claims, 'nbf')) {
    return;
  }
  const nbf = asTimestamp(claims.nbf, 'Not before');
  if (nbf > now() + leeway) {
    throw new JWTClaimsError('The token is not yet valid (nbf)');
  }
}

function validateExp(claims, leeway) {
  if (!has(claims, 'exp')) {
    return;
  }
  const exp = asTimestamp(claims.exp, 'Expiration Time');
  if (exp < now() - leeway) {
    throw new ExpiredSignatureError('Signature has expired.');
  }
}

function validateAud(claims, audience, required) {
  if (!has(claims, 'aud')) {
    if (required) {
      throw new JWTError('Audience claim expected, but not in claims');
    }
    return;
  }
  let audienceClaims = claims.aud;
  if (typeof audienceClaims === 'string') {
    audienceClaims = [audienceClaims];
  }
  if (!Array.isArray(audienceClaims)) {
    throw new JWTClaimsError('Invalid claim format in token');
  }
  if (audienceClaims.some((item) => typeof item !== 'string')) {
    throw new JWTClaimsError('Invalid claim format in token');
  }
  if (audience !== null && audience !== undefined && !audienceClaims.includes(audience)) {
    throw new JWTClaimsError('Invalid audience');
  }
}

function validateIss(claims, issuer) {
  if (issuer === null || issuer === undefined) {
    return;
  }
  const accepted = typeof issuer === 'string' ? [issuer] : issuer;
  if (!accepted.includes(claims.iss)) {
    throw new JWTClaimsError('Invalid issuer');
  }
}

/**
 * `_validate_sub`: the claim must be a string, and must equal `subject` when
 * one was supplied by the caller.
 */
function validateSub(claims, subject) {
  if (!has(claims, 'sub')) {
    return;
  }
  if (typeof claims.sub !== 'string') {
    throw new JWTClaimsError('Subject must be a string.');
  }
  if (subject !== null && subject !== undefined && claims.sub !== subject) {
    throw new JWTClaimsError('Invalid subject');
  }
}

/** `_validate_jti`: the claim must be a string. */
function validateJti(claims) {
  if (!has(claims, 'jti')) {
    return;
  }
  if (typeof claims.jti !== 'string') {
    throw new JWTClaimsError('JWT ID must be a string.');
  }
}

/**
 * @param {Record<string, unknown>} claims
 * @param {Record<string, unknown>} options merged options
 * @param {{audience?: string|null, issuer?: string|string[]|null, subject?: string|null}} context
 */
export function validateClaims(claims, options, context = {}) {
  const leeway = options.leeway ?? 0;

  if (options.verify_iat) {
    validateIat(claims);
  }
  if (options.verify_nbf) {
    validateNbf(claims, leeway);
  }
  if (options.verify_exp) {
    validateExp(claims, leeway);
  }
  if (options.verify_aud) {
    validateAud(claims, context.audience ?? null, options.require_aud);
  }
  if (options.verify_iss) {
    validateIss(claims, context.issuer ?? null);
  }
  if (options.verify_sub) {
    validateSub(claims, context.subject ?? null);
  }
  if (options.verify_jti) {
    validateJti(claims);
  }
}

/** Merges caller `options` over the library defaults. */
export function mergeOptions(options) {
  return { ...DEFAULT_OPTIONS, ...(options ?? {}) };
}

