/**
 * The `jose.jwt` public surface: `encode`, `decode`, and the unverified
 * accessors. Claims are carried in insertion order (JS object key order), which
 * is what CPython dicts guarantee and what the JWT payload byte layout depends
 * on.
 */

import { utf8Decode } from '../codec/utf8.mjs';
import { loads } from '../json/py_json.mjs';
import { ALGORITHMS } from './keys.mjs';
import * as jws from './jws.mjs';
import { mergeOptions, validateClaims } from './claims.mjs';
import { JWSError, JWTError, JOSEError } from './errors.mjs';

/**
 * `jwt.encode(claims, key, algorithm='HS256', headers=None, access_token=None)`
 * @param {Record<string, unknown>} claims
 * @param {string|Uint8Array} key
 * @param {string} [algorithm]
 * @param {Record<string, unknown>|null} [headers]
 * @returns {string}
 */
export function encode(claims, key, algorithm = ALGORITHMS.HS256, headers = null) {
  if (claims === null || typeof claims !== 'object' || Array.isArray(claims)) {
    throw new JWTError('Claims must be a mapping.');
  }
  return jws.sign(claims, key, { headers, algorithm });
}

/**
 * `jwt.decode(token, key, algorithms=None, options=None, audience=None,
 * issuer=None, subject=None, access_token=None)`
 *
 * @param {string} token
 * @param {string|Uint8Array} key
 * @param {{algorithms?: string[]|string|null, options?: Record<string, unknown>|null,
 *          audience?: string|null, issuer?: string|string[]|null,
 *          subject?: string|null}} [params]
 * @returns {Record<string, unknown>} the decoded claim set
 */
export function decode(token, key, params = {}) {
  const options = mergeOptions(params.options);
  let algorithms = params.algorithms ?? null;
  if (typeof algorithms === 'string') {
    algorithms = [algorithms];
  }

  let payload;
  try {
    payload = jws.verify(token, key, algorithms, options.verify_signature);
  } catch (err) {
    if (err instanceof JWSError) {
      throw new JWTError(err.message);
    }
    throw err;
  }

  let claims;
  try {
    claims = loads(utf8Decode(payload));
  } catch (err) {
    throw new JWTError(`Invalid payload string: ${err.message}`);
  }
  if (claims === null || typeof claims !== 'object' || Array.isArray(claims)) {
    throw new JWTError('Invalid payload string: must be a json object');
  }

  validateClaims(claims, options, {
    audience: params.audience ?? null,
    issuer: params.issuer ?? null,
    subject: params.subject ?? null,
  });

  return claims;
}

/** `jwt.get_unverified_header` */
export function getUnverifiedHeader(token) {
  try {
    return jws.getUnverifiedHeader(token);
  } catch (err) {
    if (err instanceof JOSEError) {
      throw new JWTError(err.message);
    }
    throw err;
  }
}

/** `jwt.get_unverified_claims` */
export function getUnverifiedClaims(token) {
  return loads(utf8Decode(jws.verify(token, '', null, false)));
}

export { ALGORITHMS };

