      this.exit(0);
      continue;
    }

    let value = explicitArg;
    if (value === null) {
      const next = i + 1 < args.length ? args[i + 1] : undefined;
      const nextIsOption = next !== undefined && this.parseOptional(next) !== null
        && this.parseOptional(next)[0] !== null;
      const nextIsUnknownOption = next !== undefined && next[0] === '-' && next.length > 1
