/**
 * A focused port of CPython's `argparse.ArgumentParser` covering the feature
 * set this program uses: long options with `--opt value` / `--opt=value`,
 * unique-prefix abbreviation, the automatic `-h/--help` action, `required=True`
 * enforcement, and argparse's exact usage/error/help text and exit codes.
 */

import { reprString } from './repr.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(argumentName ? `argument ${argumentName}: ${message}` : message);
    this.name = 'ArgumentError';
  }
}

function baseName(pathLike) {
  const normalized = String(pathLike).replace(/[/\\]+$/, '');
  const index = Math.max(normalized.lastIndexOf('/'), normalized.lastIndexOf('\\'));
  return index === -1 ? normalized : normalized.slice(index + 1);
}

/** `argparse` derives `prog` from `os.path.basename(sys.argv[0])`. */
export function defaultProg(argv = process.argv) {
  return baseName(argv[1] ?? 'program');
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean, exitOnError?: boolean}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? defaultProg();
    this.actions = [];
    this.optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * @param {string[]|string} flags
   * @param {{action?: string, required?: boolean, dest?: string, metavar?: string, help?: string, type?: Function, default?: unknown}} [spec]
   */
  addArgument(flags, spec = {}) {
    const optionStrings = Array.isArray(flags) ? flags.slice() : [flags];
    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = spec.dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');

    const action = {
      optionStrings,
      dest,
      action: spec.action ?? 'store',
      // `nargs` in the only two flavours needed: flags consume nothing, stores
      // consume exactly one value.
      nargs: (spec.action ?? 'store') === 'help' ? 0 : 1,
      required: spec.required ?? false,
      metavar: spec.metavar ?? dest.toUpperCase(),
      help: spec.help ?? null,
      type: spec.type ?? String,
      default: spec.default ?? null,
    };

    this.actions.push(action);
    for (const flag of optionStrings) {
      this.optionStringActions.set(flag, action);
    }
    return action;
  }

  /** `_get_action_name`: option actions are named by their joined flags. */
  static actionName(action) {
    return action.optionStrings.join('/');
  }

  formatUsage() {
    const parts = [];
    for (const action of this.actions) {
      const flag = action.optionStrings[0];
      if (action.action === 'help') {
        parts.push(`[${flag}]`);
      } else if (action.required) {
        parts.push(`${flag} ${action.metavar}`);
      } else {
        parts.push(`[${flag} ${action.metavar}]`);
      }
    }
    return `usage: ${this.prog}${parts.length ? ` ${parts.join(' ')}` : ''}\n`;
  }

  formatHelp() {
    let out = this.formatUsage();
    out += '\noptions:\n';
    for (const action of this.actions) {
      let invocation;
      if (action.action === 'help') {
        invocation = action.optionStrings.join(', ');
      } else {
        invocation = action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(', ');
      }

      const indented = `  ${invocation}`;
      if (!action.help) {
        out += `${indented}\n`;
      } else if (indented.length <= 22) {
        // argparse pads the invocation out to its max_help_position (24).
        out += `${indented.padEnd(24)}${action.help}\n`;
      } else {
        out += `${indented}\n${' '.repeat(24)}${action.help}\n`;
      }
    }
    return out;
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  printUsage(stream = process.stderr) {
    stream.write(this.formatUsage());
  }

  /** `parser.error()`: usage + message on stderr, then exit status 2. */
  error(message) {
    this.printUsage(process.stderr);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  exit(status = 0) {
    process.exit(status);
  }

  /**
   * `_parse_optional`. Returns `null` when the token is a positional, or a
   * tuple `[action|null, optionString, explicitArg|null]`.
   */
  parseOptional(argString) {
    if (!argString || argString[0] !== '-') {
      return null;
    }
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) {
      return null;
    }

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const head = argString.slice(0, eq);
      if (this.optionStringActions.has(head)) {
        return [this.optionStringActions.get(head), head, argString.slice(eq + 1)];
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const names = matches.map((match) => match[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (matches.length === 1) {
      return matches[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals()) {
      return null;
    }
    if (argString.includes(' ')) {
      return null;
    }
    return [null, argString, null];
  }

  /** `_get_option_tuples`: unique-prefix abbreviation support. */
  getOptionTuples(argString) {
    const result = [];
    const eq = argString.indexOf('=');
    const prefix = eq === -1 ? argString : argString.slice(0, eq);
    const explicitArg = eq === -1 ? null : argString.slice(eq + 1);

    if (argString.startsWith('--')) {
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          result.push([action, optionString, explicitArg]);
        }
      }
      return result;
    }

    // Single-dash: a short option may be written with its argument attached
    // (`-hx`), which argparse reports as an explicit argument.
    const shortOptionPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortOptionPrefix) {
        result.push([action, optionString, shortExplicitArg]);
      } else if (optionString.startsWith(argString)) {
        result.push([action, optionString, null]);
      }
    }
    return result;
  }

  hasNegativeNumberOptionals() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER.test(optionString)) {
        return true;
      }
    }
    return false;
  }

  /**
   * First pass of `_parse_known_args`: classify every token as `'O'`
   * (option-like), `'A'` (value-like) or `'-'` (the `--` separator, which is
   * option-like for matching purposes but is never consumed as a value here).
   * Everything after the first `--` is forced to `'A'`.
   *
   * @param {string[]} args
   */
  scanArgs(args) {
    const pattern = [];
    const tuples = [];

    let i = 0;
    for (; i < args.length; i += 1) {
      if (args[i] === '--') {
        pattern.push('-');
        tuples.push(null);
        for (i += 1; i < args.length; i += 1) {
          pattern.push('A');
          tuples.push(null);
        }
        break;
      }
      const optionTuple = this.parseOptional(args[i]);
      tuples.push(optionTuple);
      pattern.push(optionTuple === null ? 'A' : 'O');
    }

    return { pattern, tuples };
  }

  /**
   * @param {string[]} [argv] defaults to `process.argv.slice(2)`
   * @returns {[Record<string, unknown>, string[]]}
   */
  parseKnownArgs(argv) {
    const args = argv ?? process.argv.slice(2);
    const namespace = {};
    for (const action of this.actions) {
      if (action.action !== 'help') {
        namespace[action.dest] = action.default;
      }
    }

    // argparse classifies every token up front, so an ambiguous abbreviation is
    // reported even when it sits where a value was expected.
    const { pattern, tuples } = this.scanArgs(args);

    const seen = new Set();
    const extras = [];

    for (let i = 0; i < args.length; i += 1) {
      if (pattern[i] !== 'O') {
        // `--` and unmatched values alike end up unrecognized: this parser
        // defines no positional arguments to consume them.
        extras.push(args[i]);
        continue;
      }

      const [action, , explicitArg] = tuples[i];
      if (action === null) {
        extras.push(args[i]);
        continue;
      }

      if (action.action === 'help') {
        this.printHelp();
        this.exit(0);
        continue;
      }

      let value = explicitArg;
      if (value === null) {
        if (pattern[i + 1] !== 'A') {
          this.error(
            new ArgumentError(ArgumentParser.actionName(action), 'expected one argument').message,
          );
        }
        value = args[i + 1];
        i += 1;
      }

      namespace[action.dest] = action.type(value);
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * @param {string[]} [argv]
   * @returns {Record<string, unknown>}
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

