  if (payload instanceof Uint8Array) {
    return base64urlEncode(payload);
  }
  if (typeof payload === 'string') {
    return base64urlEncode(utf8Encode(payload));
  }
  return base64urlEncode(utf8Encode(dumps(payload)));
}

