    throw new JWSError('No algorithm was specified in the JWS header.');
  }
  if (algorithms !== null && algorithms !== undefined && !algorithms.includes(alg)) {
    throw new JWSError('The specified alg value is not allowed');
  }

  let preparedKey;
  try {
    preparedKey = constructKey(key, alg);
  } catch (err) {
    throw new JWSError(err.message);
  }
