/**
 * CPython `repr()` for the value shapes `print()` can receive here (str, dict,
 * list, tuple, bool, None, int, float) so that printing the decoded claim set
 * is byte-identical to Python's output.
 */

// Py_UNICODE_ISPRINTABLE: everything except the Cc/Cf/Cs/Co/Cn/Zl/Zp/Zs
// categories, with U+0020 explicitly printable.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(char) {
  return char === ' ' || !NON_PRINTABLE.test(char);
}

function escapeNonPrintable(codePoint) {
  if (codePoint < 0x100) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }
  if (codePoint < 0x10000) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a Python `str`: single quotes unless the value contains a single
 * quote but no double quote.
 * @param {string} value
 */
export function reprString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";

  let out = quote;
  for (const char of value) {
    const cp = char.codePointAt(0);
    if (char === quote || char === '\\') {
      out += `\\${char}`;
    } else if (char === '\t') {
      out += '\\t';
    } else if (char === '\n') {
      out += '\\n';
    } else if (char === '\r') {
      out += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      out += `\\x${cp.toString(16).padStart(2, '0')}`;
    } else if (cp < 0x7f || isPrintable(char)) {
      out += char;
    } else {
      out += escapeNonPrintable(cp);
    }
  }
  return out + quote;
}

/**
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) {
