    const parts = [];
    for (const action of this.actions) {
      const flag = action.optionStrings[0];
      if (action.action === 'help') {
        parts.push(`[${flag}]`);
      } else if (action.required) {
        parts.push(`${flag} ${action.metavar}`);
      } else {
        parts.push(`[${flag} ${action.metavar}]`);
      }
    }
    return `usage: ${this.prog}${parts.length ? ` ${parts.join(' ')}` : ''}\n`;
  }

  formatHelp() {
    let out = this.formatUsage();
    out += '\noptions:\n';
    for (const action of this.actions) {
