        }

        if (explicitArg !== null) {
          if (action.nargs === 0 && optionString[1] !== '-' && explicitArg !== '') {
            // A glued argument on a flag: only `-xy` can continue as another
            // short option, `-x=y` and `-x-y` are hard errors.
            if (sep || explicitArg[0] === '-') {
              this.error(
                new ArgumentError(
                  ArgumentParser.actionName(action),
                  `ignored explicit argument ${reprString(explicitArg)}`,
                ).message,
              );
            }
            actionTuples.push([action, []]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (!explicitArg) {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
              continue;
            }
            extras.push(char + explicitArg);
            break;
          }
          if (action.nargs === 1) {
            actionTuples.push([action, [explicitArg]]);
            break;
          }
          this.error(
            new ArgumentError(
              ArgumentParser.actionName(action),
              `ignored explicit argument ${reprString(explicitArg)}`,
            ).message,
          );
        }

        if (action.nargs === 0) {
          actionTuples.push([action, []]);
          break;
        }

        if (pattern[i + 1] !== 'A') {
          this.error(
            new ArgumentError(ArgumentParser.actionName(action), 'expected one argument').message,
          );
        }
        actionTuples.push([action, [args[i + 1]]]);
        i += 1;
        break;
      }

      for (const [pending, values] of actionTuples) {
        takeAction(pending, values);
      }
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => ArgumentParser.actionName(action));
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * @param {string[]} [argv]
   * @returns {Record<string, unknown>}
   */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}
